//Khatwa 1: Ta'reef al-class Animal
class Animal {
	//Khatwa 1.1: A'lin al-mutaghayar al-instance
	private String name;
	//Khatwa 1.2: Ta'reef al-constructor li insha' hayawan bi al-ism al-muwadad
	public Animal(String name) {
		this.name = name;
	}
	 //Khatwa 1.3: Ta'reef al-method li i'ta' sawt lil-hayawan
	public void speak() {
		System.out.println("Ismi " + name);
	}
	//Khatwa 1.4: Ta'reef al-method toString li al-husool ala tamtheel al-string li instance al-Animal
	public String toString() {
		return " Ism: " + name;
	}
	//Khatwa 1.5: Ta'reef al-method li al-husool ala ism al-hayawan
	public String getName() {
		return name;
	}
}
//Khatwa 2: Tawsie' al-class Animal li ta'reef class Dog
class Dog extends Animal {
	//Khatwa 2.1: A'lin al-mutaghayar al-instance
	private String owner;
	//Khatwa 2.2: Ta'reef al-constructor li insha' kalb bi al-ism wal-malek
 	public Dog(String name, String owner) {
 		super(name); 
		this.owner = owner;	
	}
	//Khatwa 2.3: Tajree al-method speak min Animal li i'ta' sawt li Dog
	public void speak() {
		super.speak();
		System.out.println("haw haw!");
	}
	//Khatwa 2.4: Tajree al-method toString min Animal li tamtheel Dog
	public String toString() {
		return super.toString() + ",  Malek: " + owner;
	}
}
